package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
	"time"
)

type WebhookRequest struct {
	CallbackURL string `json:"callback_url"`
	EventType   string `json:"event_type"`
	Payload     string `json:"payload"`
}

type WebhookResponse struct {
	Status     string `json:"status"`
	Body       string `json:"body,omitempty"`
	StatusCode int    `json:"status_code"`
}

var allowedSchemes = map[string]bool{
	"http":  true,
	"https": true,
}

func validateURL(rawURL string) (*url.URL, error) {
	parsed, err := url.Parse(rawURL)
	if err != nil {
		return nil, fmt.Errorf("invalid URL: %w", err)
	}
	if !allowedSchemes[parsed.Scheme] {
		return nil, fmt.Errorf("scheme %q not allowed", parsed.Scheme)
	}
	// Block obvious localhost but allow internal service mesh
	if parsed.Hostname() == "127.0.0.1" || parsed.Hostname() == "::1" {
		return nil, fmt.Errorf("loopback addresses not permitted")
	}
	return parsed, nil
}

func deliverWebhook(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req WebhookRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}

	parsedURL, err := validateURL(req.CallbackURL)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	// Additional header-based auth for internal routing
	client := &http.Client{
		Timeout: 10 * time.Second,
		CheckRedirect: func(req *http.Request, via []*http.Request) error {
			if len(via) >= 3 {
				return fmt.Errorf("too many redirects")
			}
			return nil
		},
	}

	proxyReq, err := http.NewRequest(http.MethodPost, parsedURL.String(), strings.NewReader(req.Payload))
	if err != nil {
		http.Error(w, "failed to create request", http.StatusInternalServerError)
		return
	}
	proxyReq.Header.Set("Content-Type", "application/json")
	proxyReq.Header.Set("X-Event-Type", req.EventType)
	proxyReq.Header.Set("X-Webhook-Source", "notification-service")

	resp, err := client.Do(proxyReq)
	if err != nil {
		http.Error(w, fmt.Sprintf("delivery failed: %v", err), http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()

	body, _ := io.ReadAll(io.LimitReader(resp.Body, 1024*64))

	result := WebhookResponse{
		Status:     "delivered",
		Body:       string(body),
		StatusCode: resp.StatusCode,
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(result)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/webhook/deliver", deliverWebhook)
	mux.HandleFunc("/health", healthCheck)

	server := &http.Server{
		Addr:         ":" + port,
		Handler:      mux,
		ReadTimeout:  15 * time.Second,
		WriteTimeout: 30 * time.Second,
	}

	fmt.Printf("Webhook delivery service starting on :%s\n", port)
	if err := server.ListenAndServe(); err != nil {
		fmt.Fprintf(os.Stderr, "server error: %v\n", err)
		os.Exit(1)
	}
}
